# Your house, inside (shack / house, levels 0-1). The doorway mat at the bottom centre leads back out;
# the code sends you to the cell below the house door wherever the house stands on the farm.
# Floor cells x 1..8, y 2..7 sit at the same coordinates in house2, so furniture survives an upgrade.
map HOUSE1 set=INTERIOR w=10 h=9 music=NONE
key L WALL_SIDE_L block
key R WALL_SIDE_R block
key T WALL_TOP block
key W WALL block
key E FLOOR_EDGE walk
key . FLOOR_WOOD walk
key X WALL_FRONT block
key C WALL_CORNER_L block
key D WALL_CORNER_R block
key M DOOR_MAT_L walk
key N DOOR_MAT_R walk
grid
LTTTTTTTTR
LWWWWWWWWR
LEEEEEEEER
L........R
L........R
L........R
L........R
L........R
CXXXMNXXXD
place WALL_WINDOW 2 0
place WALL_WINDOW 7 0
warp 4 8 FARM 0 0 down
warp 5 8 FARM 0 0 down
